(() => {
 const topics=[
 {id:'services',title:'Our services',keys:['services','service','staffing','recruitment','training','outsourcing','facility','housekeeping','security','gardening','seva'],answer:'We help with contract staffing, recruitment, outsourcing and training, skill development, facility staffing and employment verification. Tell our team what support you need.',links:[['Explore services','/services'],['Facility services','/services/facility-management']]},
 {id:'jobs',title:'Jobs & applications',keys:['job','jobs','apply','application','vacancy','vacancies','career','careers','cv','resume','f revone','frevone','naukri','नौकरी','आवेदन'],answer:'Job openings and applications are managed on Frevone. Open the current listing there to check requirements and apply. This chat cannot check an application or confirm selection.',links:[['Browse jobs on Frevone','http://gad-hrms.frevo.co.in/open-positions'],['Ask HR','mailto:hr@gadigital.in']]},
 {id:'fees',title:'Placement service fee',keys:['fee','fees','10000','10,000','11000','11,000','refund','refundable','payment','charge','charges','paisa','paise','shulk','फीस','शुल्क'],answer:'A one-time service fee of ₹10,000 is mandatory if you are placed through GA Digital Web Word. It is payable to GA Digital Web Word and is non-refundable, only after selection and a written offer. Never pay before that or to a personal bank account or UPI ID. Confirm payment instructions directly with HR; this chat does not collect payments.',links:[['Read the current notice','/public-notices'],['Contact HR','mailto:hr@gadigital.in']]},
 {id:'verification',title:'Employment verification',keys:['verification','verify','former','existing employee','employment history','experience letter','48 hours','48 hour','48','सत्यापन'],answer:'Employment verification is for existing and former employees of GA Digital Web Word. The website form prepares an email draft to HR; you must send it through your email app. If you have not received a reply within 48 hours of sending the request, follow up at hr@gadigital.in.',links:[['Verification request','/services/employment-verification'],['Email HR','mailto:hr@gadigital.in']]},
 {id:'offices',title:'Office locations',keys:['office','offices','address','location','locations','map','ghaziabad','delhi','mumbai','pata','पता','कार्यालय'],answer:'Our head office is at S-14, 2nd Floor, Aditya Mall, Indirapuram, Ghaziabad, Uttar Pradesh – 201014. The office page also lists our Delhi registered office and Mumbai office, with maps and directions.',links:[['Addresses & maps','/contact/office-locations']]},
 {id:'contact',title:'Contact a department',keys:['contact','email','mail','phone','whatsapp','department','departments','tender','hr','accounts','compliance','hrms','salary','support','helpdesk','complaint','संपर्क','वेतन'],answer:'Tender: tender@gadigital.in · HR: hr@gadigital.in · Accounts: accounts@gadigital.in · HRMS: hrms@gadigital.in. Call 0120-4218525 or chat with the company on WhatsApp at +91 9958859677. For personal salary, employment or application questions, contact the relevant team directly.',links:[['Contact form','/contact'],['WhatsApp the company','https://wa.me/919958859677']]},
 {id:'company',title:'About the company',keys:['about','company','garima','md','director','story','founded','since','2003','कंपनी'],answer:'GA Digital Web Word has supported organizations with staffing and workforce services since 2003. Garima Arora is the Managing Director.',links:[['Our Story','/about']]},
 {id:'fraud',title:'Report recruitment fraud',keys:['fraud','scam','fake','impersonation','broker','suspicious','धोखा','फर्जी'],answer:'Verify job offers and payment instructions directly with GA Digital Web Word. Do not rely on messages from people claiming to represent the company. Contact HR if you are unsure; this chat cannot verify a particular offer or sender.',links:[['Recruitment fraud information','/careers/recruitment-fraud-alert'],['Email HR','mailto:hr@gadigital.in']]}
 ];
 const launcher=document.createElement('button');launcher.type='button';launcher.className='faq-chat-launcher';launcher.setAttribute('aria-haspopup','dialog');launcher.setAttribute('aria-controls','faq-chat');launcher.setAttribute('aria-label','Website help');launcher.title='Chat with our FAQ assistant';launcher.innerHTML='<svg viewBox="0 0 32 32" aria-hidden="true" focusable="false"><path d="M7 5h18a4 4 0 0 1 4 4v12a4 4 0 0 1-4 4H14l-7 5v-5a4 4 0 0 1-4-4V9a4 4 0 0 1 4-4Z" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/><circle cx="10" cy="15" r="1.5" fill="currentColor"/><circle cx="16" cy="15" r="1.5" fill="currentColor"/><circle cx="22" cy="15" r="1.5" fill="currentColor"/></svg>';
 const dialog=document.createElement('dialog');dialog.id='faq-chat';dialog.className='faq-chat';dialog.setAttribute('aria-labelledby','faq-chat-title');
 dialog.innerHTML='<header><div><h2 id="faq-chat-title">How can we help?</h2><p>GA Digital Web Word · FAQ assistant</p></div><button type="button" class="faq-chat-close" aria-label="Close website help">×</button></header><p class="faq-chat-note">Preset website answers, not a live agent. Please do not share personal documents or sensitive details. Messages are not sent or saved.</p><div class="faq-chat-topics" aria-label="Choose a help topic"></div><div class="faq-chat-log" role="log" aria-label="Website help conversation" aria-live="polite" aria-relevant="additions"></div><form class="faq-chat-form"><label for="faq-chat-question">Your website question</label><div><input id="faq-chat-question" type="text" maxlength="300" required autocomplete="off" placeholder="Try: fees, jobs, verification…"><button type="submit">Ask</button></div></form>';
 document.body.append(launcher,dialog);
 const log=dialog.querySelector('.faq-chat-log'),input=dialog.querySelector('input'),choices=dialog.querySelector('.faq-chat-topics');
 const message=(text,links=[],user=false)=>{const block=document.createElement('div');block.className=user?'faq-chat-message user':'faq-chat-message';const p=document.createElement('p');p.textContent=text;block.append(p);links.forEach(([label,url])=>{const a=document.createElement('a');a.textContent=label+' ↗';a.href=url;if(/^https?:/.test(url)){a.target='_blank';a.rel='noopener noreferrer';}block.append(a);});log.append(block);while(log.children.length>16)log.firstElementChild.remove();block.scrollIntoView({block:'nearest'});};
 const answer=topic=>message(topic.answer,topic.links);
 topics.forEach(topic=>{const button=document.createElement('button');button.type='button';button.textContent=topic.title;button.addEventListener('click',()=>{message(topic.title,[],true);answer(topic);});choices.append(button);});
 launcher.addEventListener('click',()=>{dialog.showModal();input.focus();if(!log.children.length)message('Choose a topic above, or type a short question in English, Hindi or Hinglish. I can help with website information only.');});
 const reset=()=>{dialog.close();log.replaceChildren();input.value='';launcher.focus();};
 dialog.querySelector('.faq-chat-close').addEventListener('click',reset);
 dialog.addEventListener('cancel',event=>{event.preventDefault();reset();});
 dialog.querySelector('form').addEventListener('submit',event=>{
  event.preventDefault();const question=input.value.trim();if(!question)return;input.value='';message(question,[],true);
  const normalized=question.toLowerCase().normalize('NFKC');
  const matches=topics.map(topic=>({topic,score:topic.keys.reduce((score,key)=>{const escaped=key.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return score+(new RegExp('(^|[^\\p{L}\\p{N}])'+escaped+'($|[^\\p{L}\\p{N}])','u').test(normalized)?1:0);},0)})).filter(x=>x.score).sort((a,b)=>b.score-a.score);
  if(matches.length===1)answer(matches[0].topic);
  else if(matches.length>1)message('Your question could relate to more than one topic. Please choose the closest topic above: '+matches.slice(0,3).map(x=>x.topic.title).join(', ')+'.');
  else message('I only have preset answers about GA Digital Web Word’s website. Please choose a topic above. For a question not covered here, contact our team.',[['Contact the team','/contact'],['WhatsApp','https://wa.me/919958859677']]);
 });
})();
